package com.multitenanterp.payroll;
import com.multitenanterp.platform.tenant.TenantContext;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.io.IOException;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.util.*;
@Service
public class VariableInputCsvImportService{
 static final List<String> REQUIRED_HEADERS=List.of("employeeNumber","code","name","inputType","amount");private final JdbcClient db;private final PayrollInputService inputs;public VariableInputCsvImportService(JdbcClient db,PayrollInputService inputs){this.db=db;this.inputs=inputs;}
 public VariableInputImportResult importCsv(MultipartFile file,int year,int month,String actor){if(year<2000||year>2200||month<1||month>12)throw bad("Invalid payroll period");if(file==null||file.isEmpty())throw bad("CSV file is required");String content;try{content=new String(file.getBytes(),StandardCharsets.UTF_8);}catch(IOException e){throw bad("CSV file could not be read");}List<List<String>> parsed=parse(content);if(parsed.isEmpty())throw bad("CSV file has no header row");Map<String,Integer> headers=headers(parsed.getFirst());for(String name:REQUIRED_HEADERS)if(!headers.containsKey(name))throw bad("Missing required CSV column: "+name);List<VariableInputImportRowResult> results=new ArrayList<>();Set<String> fileKeys=new HashSet<>();for(int index=1;index<parsed.size();index++){List<String> row=parsed.get(index);if(row.stream().allMatch(String::isBlank))continue;int rowNumber=index+1;try{String employeeNumber=value(row,headers,"employeeNumber").toUpperCase(Locale.ROOT);String code=value(row,headers,"code").toUpperCase(Locale.ROOT);if(!fileKeys.add(employeeNumber+"|"+code))throw bad("Duplicate employee and code in CSV");UUID employee=employee(employeeNumber);String type=value(row,headers,"inputType").toUpperCase(Locale.ROOT);if(!Set.of("EARNING","DEDUCTION").contains(type))throw bad("inputType must be EARNING or DEDUCTION");BigDecimal amount;try{amount=new BigDecimal(value(row,headers,"amount"));}catch(NumberFormatException e){throw bad("amount must be a valid number");}if(amount.signum()<0)throw bad("amount must not be negative");PayrollVariableInput saved=inputs.saveVariable(null,new SavePayrollVariableInputRequest(employee,year,month,code,value(row,headers,"name"),type,amount,optional(row,headers,"notes")),actor);results.add(new VariableInputImportRowResult(rowNumber,true,saved.id(),null));}catch(Exception e){results.add(new VariableInputImportRowResult(rowNumber,false,null,message(e)));}}int accepted=(int)results.stream().filter(VariableInputImportRowResult::accepted).count();return new VariableInputImportResult(results.size(),accepted,results.size()-accepted,List.copyOf(results));}
 static List<List<String>> parse(String content){List<List<String>> rows=new ArrayList<>();List<String> row=new ArrayList<>();StringBuilder value=new StringBuilder();boolean quoted=false;for(int i=0;i<content.length();i++){char c=content.charAt(i);if(c=='"'){if(quoted&&i+1<content.length()&&content.charAt(i+1)=='"'){value.append('"');i++;}else quoted=!quoted;}else if(c==','&&!quoted){row.add(value.toString().trim());value.setLength(0);}else if((c=='\n'||c=='\r')&&!quoted){if(c=='\r'&&i+1<content.length()&&content.charAt(i+1)=='\n')i++;row.add(value.toString().trim());value.setLength(0);rows.add(row);row=new ArrayList<>();}else value.append(c);}if(quoted)throw bad("CSV contains an unterminated quoted value");if(value.length()>0||!row.isEmpty()){row.add(value.toString().trim());rows.add(row);}return rows;}
 private UUID employee(String number){return db.sql("SELECT id FROM employment WHERE tenant_id=:tenant AND employee_number=:number").param("tenant",TenantContext.requireTenantId()).param("number",number).query(UUID.class).optional().orElseThrow(()->bad("Employee not found: "+number));}private static Map<String,Integer> headers(List<String> values){Map<String,Integer> result=new HashMap<>();for(int i=0;i<values.size();i++){String name=values.get(i).strip();if(i==0)name=name.replace("\uFEFF","");if(!name.isEmpty())result.put(name,i);}return result;}private static String value(List<String> row,Map<String,Integer> headers,String name){String value=optional(row,headers,name);if(value==null)throw bad("Missing value: "+name);return value;}private static String optional(List<String> row,Map<String,Integer> headers,String name){Integer i=headers.get(name);if(i==null||i>=row.size()||row.get(i).isBlank())return null;return row.get(i).trim();}private static String message(Exception e){if(e instanceof ResponseStatusException r&&r.getReason()!=null)return r.getReason();return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}private static ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
}
